  if (category === "data") return "\u8D44\u6599\u5206\u6790\u4E0E\u8BA1\u7B97";
  if (category === "graphic")
    return "\u56FE\u5F62\u63A8\u7406\u7A7A\u95F4\u601D\u7EF4";
